{"content": "import sys, re, html, io, os, glob, base64, urllib.parse

sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

def decode_aurl(u):
    m = re.search(r'[?&]aurl=([^&]+)', u)
    if not m:
        return None
    s = urllib.parse.unquote(m.group(1))
    pad = '=' * (-len(s) % 4)
    try:
        return base64.urlsafe_b64decode(s + pad).decode('utf-8', 'replace')
    except Exception as e:
        return f'ERR {e}'

files = sorted(glob.glob(sys.argv[1]))
seen = set()
for path in files:
    tag = os.path.basename(path).replace('.html', '')
    with open(path, encoding='utf-8', errors='replace') as f:
        raw = f.read()
    print('#' * 90)
    print('TAG:', tag)
    print('#' * 90)
    for m in re.finditer(r'<h3[^>]*class="res-title[^"]*"[^>]*>\s*<a[^>]*href="([^"]+)"[^>]*>(.*?)</a>', raw, re.S):
