sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

def extract(path):
    raw = open(path, encoding='utf-8', errors='replace').read()
    # find JSON-ish offer objects: look for "title"/"subject" near "price"
    out = []
    # 1688 hamlet embeds data in window.__INIT_DATA or similar; scan for offerid+price windows
    for m in re.finditer(r'offer/(\d{9,})\.html', raw):
        oid = m.group(1)
        win = raw[max(0, m.start()-3000): m.start()+3000]
        prices = re.findall(r'"price"\s*:\s*"?([\d.]+)', win)
        titles = re.findall(r'"(?:title|subject|name)"\s*:\s*"([^"]{4,200})"', win)
        # decode unicode escapes
        def dec(s):
            try:
                return json.loads('"' + s + '"')
            except Exception:
                return s
        out.append((oid, prices[:3], [dec(t) for t in titles[:3]]))
    return out

for path in sys.argv[1:]:
    print('=' * 100)
    print('FILE:', os.path.basename(path))
    print('=' * 100)
    seen = set()
    for oid, prices, titles in extract(path):
        if oid in seen:
            continue
        seen.add(oid)
        print(f'  offer {oid}  prices={prices}')
        for t in titles:
            print(f'      T: {t}')
