{"content": "import sys, re, html, io, json, os

sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

KEYWORDS = ['摄像头', '摄像', 'OV2710', 'IMX307', 'webcam', '相机', '模组']

def decode_esc(s):
    try:
        return json.loads('"' + s + '"')
    except Exception:
        try:
            return s.encode().decode('unicode_escape')
        except Exception:
            return s

def extract(path):
    raw = open(path, encoding='utf-8', errors='replace').read()
    res = {}
    # Find every occurrence of a "title"/subject-like string and then locate nearest price BEFORE it in a window
    pat = re.compile(r'"(?:title|subject|name|offerTitle)"\s*:\s*"((?:[^"\\]|\\.){4,300})"')
    for m in pat.finditer(raw):
        title = decode_esc(m.group(1))
        if not any(k in title for k in KEYWORDS):
            continue
        # prices preceding this title within 2500 chars (1688 puts price before title in card JSON)
        before = raw[max(0, m.start()-2500):m.start()]
        after = raw[m.end():m.end()+2500]
        pm = re.findall(r'"price"\s*:\s*"?([\d.]+)', before)
        pm2 = re.findall(r'"price"\s*:\s*"?([\d.]+)', after)
        price = pm[-1] if pm else (pm2[0] if pm2 else '?')
        # find offer id near
        oidm = re.search(r'offer/(\d{9,})\.html', after) or re.search(r'offer/(\d{9,})\.html', before)
        oid = oidm.group(1) if oidm else ''
        if title not in res or (res[title][0] == '?' and price != '?'):
            res[title] = (price, oid)
    return res

for path in sys.argv[1:]:
    print('=' * 100)
    print('FILE:', os.path.basename(path))
    print('=' * 100)
    r = extract(path)
    for t, (p, oid) in r.items():
        print(f'  ¥{p:<10} | {t[:95]}')
        if oid:
            print(f'               https://detail.1688.com/offer/{oid}.html')
    if not r:
        print('  (no camera offers found)')
