{"content": "import sys, re, html, io, os

sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

def clean(s):
    s = re.sub(r'<script.*?</script>', ' ', s, flags=re.S)
    s = re.sub(r'<style.*?</style>', ' ', s, flags=re.S)
    s = re.sub(r'<[^>]+>', ' ', s)
    s = html.unescape(s)
    return re.sub(r'\s+', ' ', s).strip()

# Baidu results embed JSON like {"title":"...","url":"...","abstract":"..."}
for path in sys.argv[1:]:
    print('=' * 100)
    print('FILE:', os.path.basename(path))
    print('=' * 100)
    raw = open(path, encoding='utf-8', errors='replace').read()
    seen = set()
    cnt = 0
    for m in re.finditer(r'\{"[^{}]{0,80}?"(?:title|titleText)"\s*:\s*"((?:[^"\\]|\\.){8,200})"', raw):
        t = m.group(1)
        try:
            import json
            t = json.loads('"' + t + '"')
        except Exception:
            pass
        if t in seen:
            continue
        seen.add(t)
        win = raw[m.start():m.start()+2500]
        am = re.search(r'"(?:abstract|contentText|abs|summary)"\s*:\s*"((?:[^"\\]|\\.){10,600})"', win)
        um = re.search(r'"(?:url|linkUrl|jumpUrl)"\s*:\s*"(http[^"]{10,300})"', win)
        abst = ''
        if am:
            try:
                import json
                abst = json.loads('"' + am.group(1) + '"')
            except Exception:
                abst = am.group(1)
        abst = re.sub(r'<[^>]+>', '', abst)
        if any(k in (t + abst) for k in ['三脚架', '螺丝', '螺纹', '1/4', 'MJPEG', '曝光', '免驱', '摄像头']):
            cnt += 1
            print(f'\n[{cnt}] {t}')
            if um:
                print(f'    U: {um.group(1)[:180]}')
            print(f'    A: {abst[:400]}')
        if cnt > 18:
            break
    if cnt == 0:
        print('(none) raw snippet:', clean(raw)[:600])
